  factory BookBook.fromJson(Map<String, dynamic> json) => BookBook(
        id: gqlInt(json['id']),
        title: json['title']?.toString(),
        author: json['author']?.toString(),
        isbn: json['isbn']?.toString(),
        description: json['description']?.toString(),
        publishedYear: gqlInt(json['publishedYear']),
        categories: (json['categories'] as List?)?.map((e) => (e == null ? null : BookCategory.fromJson((e as Map).cast<String, dynamic>()))!).toList(),
        coverUrl: json['coverUrl']?.toString(),
        createdAt: json['createdAt']?.toString(),
        updatedAt: json['updatedAt']?.toString(),
        chapterCount: gqlInt(json['chapterCount']),
      );

  Map<String, dynamic> toJson() => {
        'id': ?id,
        'title': ?title,
        'author': ?author,
        'isbn': ?isbn,
        'description': ?description,
        'publishedYear': ?publishedYear,
        if (categories != null) 'categories': categories!.map((e) => e.toJson()).toList(),
        'coverUrl': ?coverUrl,
        'createdAt': ?createdAt,
        'updatedAt': ?updatedAt,
        'chapterCount': ?chapterCount,
      };
}

