  final List<CrmContact>? contacts;
  final List<CrmContract>? contracts;
  final List<CrmOpportunity>? opportunities;

  factory CrmAccountOverview.fromJson(Map<String, dynamic> json) => CrmAccountOverview(
        account: json['account'] == null ? null : CrmAccount.fromJson((json['account'] as Map).cast<String, dynamic>()),
        contacts: (json['contacts'] as List?)?.map((e) => (e == null ? null : CrmContact.fromJson((e as Map).cast<String, dynamic>()))!).toList(),
        contracts: (json['contracts'] as List?)?.map((e) => (e == null ? null : CrmContract.fromJson((e as Map).cast<String, dynamic>()))!).toList(),
        opportunities: (json['opportunities'] as List?)?.map((e) => (e == null ? null : CrmOpportunity.fromJson((e as Map).cast<String, dynamic>()))!).toList(),
      );

  Map<String, dynamic> toJson() => {
        if (account != null) 'account': account!.toJson(),
        if (contacts != null) 'contacts': contacts!.map((e) => e.toJson()).toList(),
        if (contracts != null) 'contracts': contracts!.map((e) => e.toJson()).toList(),
        if (opportunities != null) 'opportunities': opportunities!.map((e) => e.toJson()).toList(),
      };
}

