      );

  Map<String, dynamic> toJson() => {
        'wishlist_id': ?wishlistId,
        'wishlist_name': ?wishlistName,
        'line_id': ?lineId,
        'quantity': ?quantity,
      };
}

class WishlistProductStat {
  const WishlistProductStat({
    this.productId,
    this.title,
    this.wishlistCount,
    this.totalQuantity,
  });

  final int? productId;
  final String? title;
  final int? wishlistCount;
  final int? totalQuantity;

  factory WishlistProductStat.fromJson(Map<String, dynamic> json) => WishlistProductStat(
        productId: gqlInt(json['product_id']),
        title: json['title']?.toString(),
        wishlistCount: gqlInt(json['wishlist_count']),
        totalQuantity: gqlInt(json['total_quantity']),
      );

  Map<String, dynamic> toJson() => {
        'product_id': ?productId,
        'title': ?title,
        'wishlist_count': ?wishlistCount,
        'total_quantity': ?totalQuantity,
      };
}

class WishlistUpdateInput {
  const WishlistUpdateInput({
    this.name_,
    this.visibility,
    this.regenerateKey,
  });

  final String? name_;
  final String? visibility;
  final bool? regenerateKey;

  factory WishlistUpdateInput.fromJson(Map<String, dynamic> json) => WishlistUpdateInput(
        name_: json['name']?.toString(),
        visibility: json['visibility']?.toString(),
        regenerateKey: json['regenerate_key'] as bool?,
      );

  Map<String, dynamic> toJson() => {
